        "testata": "Internazionale",
        "lingua_originale": "it",
        "titolo_orig": "Divieto di protestare",
        "testo_it": "Pubblicato il libro 'Divieto di protestare' di Annalisa Camilli sulle recenti restrizioni alle manifestazioni in Italia.",
        "priorita": "Bassa",
        "id_gruppo": 0,
        "link": "https://www.internazionale.it/notizie/annalisa-camilli/2026/05/09/divieto-di-protestare",
